node -e "
const XLSX = require('xlsx');

// OCR result lines
const data = [
  ['Employee Handbook'],
  [''],
  ['Welcome to the company. This handbook outlines our policies.']
];

// Create workbook and worksheet
const wb = XLSX.utils.book_new();
const ws = XLSX.utils.aoa_to_sheet(data);

// Set column width for readability
ws['!cols'] = [{ wch: 55 }];

XLSX.utils.book_append_sheet(wb, ws, 'OCR Result');
XLSX.writeFile(wb, '/workspace/handbook_ocr.xlsx');
console.log('Created /workspace/handbook_ocr.xlsx');
"

